-- Package 1 (0067 + 0072 + 0073) — POSTCHECK. READ ONLY: one SELECT, changes nothing.
-- Run once right after pkg1_apply.sql. Every row must be ok = true.
-- The rows of 0067_postcheck.sql, 0072_postcheck.sql and 0073_postcheck.sql, unchanged, each item prefixed
-- with its migration; 0072's "post_match: the 0072 version" is left out because 0073 replaces that function
-- (0073's own rows check the new version).
with checks(item, ok, detail) as (
  select '0067 matches.court_lost_at: nullable timestamptz',
    exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'matches'
            and column_name = 'court_lost_at' and data_type = 'timestamp with time zone' and is_nullable = 'YES'), ''
  union all select '0067 no game has court_lost_at set yet (nothing writes it before M3-H)',
    not exists (select 1 from matches where court_lost_at is not null), ''
  union all select '0067 matches_closed_reason_check allows full / organizer / no_court',
    (select pg_get_constraintdef(oid) from pg_constraint where conname = 'matches_closed_reason_check')
      = 'CHECK ((closed_reason = ANY (ARRAY[''full''::text, ''organizer''::text, ''no_court''::text])))',
    coalesce((select pg_get_constraintdef(oid) from pg_constraint where conname = 'matches_closed_reason_check'), 'missing')
  union all select '0067 match_detail(uuid) is the verified version',
    (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bc1682b6c836fdae0b82a5d4a3463c7a'
     from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail'),
    coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail'), 'missing')
  union all select '0067 match_detail: security definer, search_path public, read-only (stable)',
    exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_detail'
            and prosecdef and provolatile = 's' and proconfig @> array['search_path=public']), ''
  union all select '0067 match_detail returns 31 columns',
    (select count(*) = 31 from pg_proc p, unnest(p.proargmodes) m where p.pronamespace = 'public'::regnamespace and p.proname = 'match_detail' and m = 't'), ''
  union all select '0067 signed-in users may call match_detail',
    has_function_privilege('authenticated', 'public.match_detail(uuid)', 'execute'), ''
  union all select '0067 anonymous visitors may not call match_detail',
    not has_function_privilege('anon', 'public.match_detail(uuid)', 'execute'), ''
  union all select '0072 join_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '47e042026bc084f8da0664020b77e1fb' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select '0072 leave_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '0bb6d58b5415a58c61878d0f4df230dd' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), 'missing')
  union all select '0072 decide_join: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '504c193753ecdda87b461204e1e0243f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), 'missing')
  union all select '0072 set_match_status: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '883dc68e447d0f8a5af681d8f395bf3b' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), 'missing')
  union all select '0072 update_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'efc91a08d70e84de15fced731b99a03c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), 'missing')
  union all select '0072 sync_match_with_booking: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '6d2108ade98ace105a863878e8bf9b3d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), 'missing')
  union all select '0072 match_message_notify: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'c063c6d3f6071aa1a6446682cad26491' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), 'missing')
  union all select '0072 notify_waiting: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '147e1455408441356f06330b177952af' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'notify_waiting'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'notify_waiting'), 'missing')
  union all select '0072 remove_player: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '16aa48b9507019f62b35e77d4fb63763' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), 'missing')
  union all select '0072 resolve_court: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'a1fb427e8c034c6fee12876f342d3460' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), 'missing')
  union all select '0072 match_message_guard: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'd58b98d66bb5d8d5033a99069c411615' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), 'missing')
  union all select '0072 push_text: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'b774b9226e3b8c68b25004b18d28289e' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'push_text'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'push_text'), 'missing')
  union all select '0072 chat insert guard: trigger match_messages_guard, before insert, enabled', exists (select 1 from pg_trigger where tgname = 'match_messages_guard' and tgrelid = 'public.match_messages'::regclass and tgenabled = 'O' and (tgtype & 2) = 2 and (tgtype & 4) = 4), ''
  union all select '0072 remove_player, resolve_court: signed-in users only', has_function_privilege('authenticated', 'public.remove_player(uuid,uuid)', 'execute') and not has_function_privilege('anon', 'public.remove_player(uuid,uuid)', 'execute') and has_function_privilege('authenticated', 'public.resolve_court(uuid,uuid)', 'execute') and not has_function_privilege('anon', 'public.resolve_court(uuid,uuid)', 'execute'), ''
  union all select '0072 notify_waiting: not callable through the API', not has_function_privilege('authenticated', 'public.notify_waiting(uuid)', 'execute') and not has_function_privilege('anon', 'public.notify_waiting(uuid)', 'execute'), ''
  union all select '0072 push_text: delivery role (service_role) only', has_function_privilege('service_role', 'public.push_text(uuid)', 'execute') and not has_function_privilege('authenticated', 'public.push_text(uuid)', 'execute') and not has_function_privilege('anon', 'public.push_text(uuid)', 'execute'), ''
  union all select '0072 game functions still callable by signed-in users (join, leave, decide, status, edit, post, hide)', (select bool_and(has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('join_match','leave_match','decide_join','set_match_status','update_match','post_match','hide_match')), ''
  union all select '0073 post_match: exactly one, the 0073 version (with p_token)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '6a8feb9a5b8c59e81d8d72ac49076635' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select '0073 post_match takes p_token last, default null (the website''s ten named arguments still resolve)', (select pg_get_function_arguments(oid) like '%p_join_mode text DEFAULT ''open''::text, p_token uuid DEFAULT NULL::uuid' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), (select pg_get_function_arguments(oid) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match')
  union all select '0073 post_match: signed-in users and the service role only', has_function_privilege('authenticated', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute') and has_function_privilege('service_role', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute') and not has_function_privilege('anon', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute'), ''
  union all select '0073 matches.client_token and its unique index per organiser', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'matches' and column_name = 'client_token') and exists (select 1 from pg_indexes where indexname = 'matches_organizer_client_token' and indexdef like '%UNIQUE%(organizer_id, client_token)%'), ''
)
select item, ok, detail from checks order by item;
